base.styles:
:root { font-family: 'Noto Sans SC','Microsoft YaHei',system-ui,sans-serif; color:#202822; background:#f1efe9; font-synthesis:none; }
* { box-sizing:border-box; } body { margin:0; } button { font:inherit; cursor:pointer; }
.dashboard-header { display:flex; align-items:center; justify-content:space-between; gap:12px; background:#fcfbf7; border-bottom:1px solid #dcded4; padding:18px clamp(18px,4vw,58px); }
.brand { font:700 22px Georgia,serif; } .brand span { color:#a56e27; } .brand small { font:500 11px system-ui,sans-serif; margin-left:11px; color:#69736b; }
.source-badge { font-size:11px; color:#69736b; } .dashboard-main { max-width:1200px; margin:24px auto; padding:34px clamp(18px,4vw,58px) 70px; background:#fcfbf7; border:1px solid #dcded4; }
.eyebrow { color:#a56e27; font-size:10px; letter-spacing:.13em; font-weight:700; }
h1 { font:600 clamp(28px,4vw,42px)/1.25 Georgia,'Noto Serif SC',serif; margin:10px 0; }
h2 { font-size:17px; margin:0; } p { line-height:1.75; } .subtitle { color:#69736b; font-size:13px; margin-bottom:30px; }
.asset-tabs { display:flex; gap:9px; flex-wrap:wrap; margin:0 0 22px; } .asset-tabs button { background:#fcfbf7; color:#69736b; border:1px solid #dcded4; border-radius:6px; padding:8px 12px; font-size:12px; }
.asset-tabs button[aria-current="true"] { color:#a56e27; border-color:#a56e27; }
.empty-state,.chart-empty { color:#69736b; padding:55px 10px; text-align:center; }
.metric-row { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:0; margin-bottom:0; border-top:1px solid #dcded4; border-bottom:1px solid #dcded4; }
.metric-row > div { padding:18px; border-right:1px solid #dcded4; } .metric-row > div:last-child { border-right:0; } .chart-panel,.table-panel { padding:24px 0; border-bottom:1px solid #dcded4; } .detail-grid article { padding:20px; border-right:1px solid #dcded4; border-bottom:1px solid #dcded4; } .detail-grid article:nth-child(2n) { border-right:0; } .realtime { padding:18px 0; border-top:1px solid #dcded4; border-bottom:1px solid #dcded4; }
.metric-row span,.metric-row small { display:block; color:#69736b; font-size:11px; } .metric-row strong { display:block; font-size:24px; margin:7px 0; }
.positive { color:#a63e34; } .negative { color:#2f7962; }
.section-head { display:flex; justify-content:space-between; align-items:center; gap:12px; margin-bottom:20px; }
.section-head > span { color:#69736b; font-size:12px; } .section-head h2 { margin-top:7px; }
.chart-panel svg { display:block; width:100%; height:260px; overflow:visible; } .axis { stroke:#dcded4; stroke-width:1; } .trend { fill:none; stroke:#a56e27; stroke-width:3; vector-effect:non-scaling-stroke; stroke-linecap:round; stroke-linejoin:round; }
.candle-up line,.candle-up rect { stroke:#bb483e; fill:#bb483e; } .candle-down line,.candle-down rect { stroke:#2f8068; fill:#2f8068; } .candle-up line,.candle-down line { stroke-width:2; vector-effect:non-scaling-stroke; }
.ma60 { fill:none; stroke:#4a806a; stroke-width:2; vector-effect:non-scaling-stroke; stroke-dasharray:6 4; } .chart-axis i { display:inline-block; width:13px; height:2px; vertical-align:middle; margin:0 8px 0 3px; } .legend-close { background:#a56e27; } .legend-ma60 { background:#4a806a; }
.volume-chart { margin-top:14px; border-top:1px solid #dcded4; padding-top:12px; } .volume-chart h3 { margin:0 0 6px; font-size:12px; color:#69736b; } .volume-chart svg { height:70px; } .volume-up { fill:#85ac97; } .volume-rise { fill:#ce7772; } .volume-fall { fill:#78ad99; }
.table-panel { margin-top:0; } .table-scroll { overflow:auto; } table { width:100%; border-collapse:collapse; font-size:12px; min-width:600px; } th,td { padding:10px 12px; border-bottom:1px solid #dcded4; text-align:right; } th:first-child,td:first-child { text-align:left; } th { color:#69736b; font-weight:600; }
.section-gap { margin-top:16px; } .compact { margin:16px 0 0; } .compact strong { font-size:18px; } .empty-note { color:#a63e34; font-size:13px; } .table-panel > .detail-grid,.chart-panel > .detail-grid { margin-top:18px; }
.revenue-chart { margin:4px 0 18px; } .revenue-chart svg { display:block;width:100%;height:180px; }
.chart-axis { display:flex; justify-content:space-between; color:#69736b; font-size:11px; margin-top:10px; }
.detail-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:0; margin-top:0; } .detail-grid article { min-height:190px; }
dl { margin:0; } dl div { display:flex; justify-content:space-between; gap:12px; padding:8px 0; border-bottom:1px solid #dcded4; font-size:12px; } dt { color:#69736b; } dd { margin:0; text-align:right; overflow-wrap:anywhere; }
.detail-grid p { color:#69736b; font-size:12px; } .realtime { display:flex; align-items:center; flex-wrap:wrap; gap:14px; margin-top:16px; }
.realtime div { flex:1; } .realtime p { font-size:12px; color:#69736b; margin:5px 0 0; } .realtime button { border:0; background:#a56e27; color:#fff; padding:9px 13px; border-radius:6px; font-size:12px; }
.realtime > span { width:100%; overflow-wrap:anywhere; font-size:11px; } .error { color:#a63e34; }
@media(max-width:620px) { .dashboard-main { margin:0; border-left:0; border-right:0; padding-top:30px; } .metric-row { grid-template-columns:1fr; } .metric-row > div { border-right:0; border-bottom:1px solid #dcded4; } .metric-row > div:last-child { border-bottom:0; } .detail-grid { grid-template-columns:1fr; } .detail-grid article { border-right:0; } .dashboard-header { align-items:flex-start; } .source-badge { max-width:120px; text-align:right; } }

.bar-inspector { display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;padding:12px 0;margin:5px 0 8px;border-top:1px solid #dcded4;border-bottom:1px solid #dcded4;font-size:12px;font-variant-numeric:tabular-nums; }
.bar-inspector strong { color:#21382e;font-size:13px; }
.bar-inspector span { color:#3f4c43;white-space:nowrap; }
.bar-inspector .positive { color:#a63e34; }.bar-inspector .negative { color:#16806a; }
.chart-panel svg[tabindex] { cursor:crosshair;touch-action:pan-y; }
.chart-panel svg[tabindex]:focus-visible { outline:2px solid #a56e27;outline-offset:3px; }
.crosshair { stroke:#8b744a;stroke-width:1;stroke-dasharray:3 3;pointer-events:none; }
.announcement-list { margin:0;padding:0;list-style:none; }.announcement-list li { padding:9px 0;border-bottom:1px solid #dcded4;font-size:12px; }
.live-data { font-variant-numeric:tabular-nums; }

.conclusion-list { margin:8px 0;padding-left:18px;color:#4b594d;font-size:12px;line-height:1.7; } .conclusion-list li { margin:4px 0; }

.volume-rise{fill:#e9a8a9}.volume-fall{fill:#97d1bb}.volume-chart svg{cursor:crosshair;touch-action:pan-y}.volume-chart svg:focus-visible{outline:2px solid #a56e27;outline-offset:2px}

